class Stack:
    """A LIFO stack. pop() and peek() raise IndexError("empty stack") when empty."""
    def __init__(self):
        self.items = []
    def push(self, x):
        self.items.append(x)
    def pop(self):
        if not self.items:
            return None
        return self.items.pop()
    def peek(self):
        return self.items[0]
    def __len__(self):
        return len(self.items)

