def parse_amount(text):
    """Turn a receipt amount such as "$1,204.50" or "-$12.00" into cents (int)."""
    cleaned = text.strip().replace("$", "").replace(",", "")
    return int((Decimal(cleaned) * 100).to_integral_value())


