    """lines look like: "2026-08-03 | Greenleaf | groceries | $84.17".
    Return {category: total_cents}. Refunds are written with a leading minus."""
    totals = {}
    for line in lines:
        if not line.strip():
            continue
        _date, _merchant, category, amount = [p.strip() for p in line.split("|")]
        totals[category] = totals.get(category, 0) + parse_amount(amount)
    return totals

