def paid_hours(shifts):
    """shifts: list of (start "HH:MM", end "HH:MM") in 24-hour time.
    A shift whose end is earlier than its start crosses midnight.
    Shifts LONGER than 6 hours have an unpaid 30-minute break deducted.
    Returns total paid hours as a float rounded to 2 decimals."""
    total = 0
    for start, end in shifts:
        length = minutes(end) - minutes(start)
